	// 6. Sync approved mapping rules → ALTER TABLE ADD COLUMN (restored from pre-refactor L804-926)
	columnsAdded := 0
	columnsAlteredType := 0
	var ddlErrors []string
	var rules []mastermodel.MappingRuleV2
	var rulesErr error
	if payload.ShadowShadowID > 0 {
		rules, rulesErr = h.mappingV2Repo.ListActiveBySourceObjectAndBinding(ctx, effectiveID, payload.ShadowShadowID)
	} else {
		rules, rulesErr = h.mappingV2Repo.ListActiveBySourceObject(ctx, effectiveID)
	}
	if rulesErr != nil {
		observability.Ctx(ctx, h.Logger).Error("failed to load mapping_rule_v2 for ALTER",
			zap.Int64("source_object_id", effectiveID),
			zap.Int64("shadow_binding_id", payload.ShadowShadowID),
			zap.Error(rulesErr),
		)
		ddlErrors = append(ddlErrors, fmt.Sprintf("load mapping_rule_v2: %v", rulesErr))
	} else {
		existingColsWithType := h.schemaAdapter.ListColumnsWithType(ctx, schemaName, payload.TargetTable)
		columnsSkipped := 0
		columnsAlreadyExist := 0
		for _, rule := range rules {
			colLower := strings.ToLower(strings.TrimSpace(rule.TargetColumn))
			if existingType, ok := existingColsWithType[colLower]; ok {
				if normalizePGType(rule.DataType) == normalizePGType(existingType) {
					columnsAlreadyExist++
					continue
				}
				// Type drift: ALTER COLUMN TYPE
				observability.Ctx(ctx, h.Logger).Warn("column type drift detected, altering",
					zap.String("column", rule.TargetColumn),
					zap.String("rule_type", rule.DataType),
					zap.String("existing_type", existingType),
				)
				if err := h.schemaAdapter.AlterColumn(ctx, schemaName, payload.TargetTable, rule.TargetColumn, rule.DataType, "alter_type"); err != nil {
					observability.Ctx(ctx, h.Logger).Error("failed to ALTER COLUMN TYPE (drift fix)",
						zap.String("column", rule.TargetColumn),
						zap.String("from_type", existingType),
						zap.String("to_type", rule.DataType),
						zap.Error(err),
					)
					ddlErrors = append(ddlErrors, fmt.Sprintf("%s (%s -> %s): %v", rule.TargetColumn, existingType, rule.DataType, err))
					columnsSkipped++
					continue
				}
				columnsAlteredType++
				existingColsWithType[colLower] = strings.ToLower(rule.DataType)
				continue
			}
			// Column doesn't exist → ADD
			alterSQL := fmt.Sprintf(`ALTER TABLE %s.%s ADD COLUMN IF NOT EXISTS %s %s`,
				sqlutil.QuoteIdent(schemaName), sqlutil.QuoteIdent(payload.TargetTable),
				sqlutil.QuoteIdent(rule.TargetColumn), rule.DataType)
			if err := h.schemaAdapter.AlterColumn(ctx, schemaName, payload.TargetTable, rule.TargetColumn, rule.DataType, "add"); err != nil {
				observability.Ctx(ctx, h.Logger).Warn("failed to add column",
					zap.String("column", rule.TargetColumn),
					zap.String("data_type", rule.DataType),
					zap.String("sql", alterSQL),
					zap.Error(err),
				)
				ddlErrors = append(ddlErrors, fmt.Sprintf("%s (add %s): %v", rule.TargetColumn, rule.DataType, err))
				columnsSkipped++
				continue
			}
			existingColsWithType[colLower] = strings.ToLower(rule.DataType)
			columnsAdded++
		}
		if columnsAdded > 0 || columnsAlteredType > 0 {
			h.schemaAdapter.InvalidateCacheInSchema(schemaName, payload.TargetTable)
			if h.NatsConn != nil {
				_ = h.NatsConn.Publish("schema.config.reload", []byte(payload.TargetTable))
			}
		}
		observability.Ctx(ctx, h.Logger).Info("ALTER TABLE summary",
			zap.String("table", payload.TargetTable),
			zap.Int("rules_total", len(rules)),
			zap.Int("columns_added", columnsAdded),
			zap.Int("columns_altered_type", columnsAlteredType),
			zap.Int("columns_already_exist", columnsAlreadyExist),
			zap.Int("columns_skipped", columnsSkipped),
		)

	}

